#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Values live in their own gitignored file, apart from backend/.env (the app's secrets).
ENV_FILE="$ROOT/.deploy.env"
PYTHON="$ROOT/backend/.venv/bin/python"

banner "Deploy LegalLens: backend on a Hugging Face Space, frontend on Vercel"

stage "Hugging Face: token and Space name"
say "The backend runs as a Docker Space on Hugging Face (free CPU tier, 16 GB RAM)."
open_url "https://huggingface.co/settings/tokens"
step "Sign up or log in first if you need to: https://huggingface.co/join"
step "Click 'Create new token', choose the 'Write' tab, name it legallens-deploy, create it."
step "Copy the token (it starts hf_). It is shown only once."
ask_secret HF_TOKEN "Paste the token:"
write_env HF_TOKEN "$HF_TOKEN"
say ""
step "Pick a name for the Space as USER/SPACE, e.g. yourname/legallens-api."
note "USER is your Hugging Face username. Letters, digits, '-', '_' and '.' only."
while true; do
  ask HF_SPACE "Space id:"
  [[ "$HF_SPACE" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] && break
  warn "That is not in USER/SPACE form. Try again."
done
write_env HF_SPACE "$HF_SPACE"

stage "Upload the backend to the Space"
say "This uploads the backend code and the built Corpus (about 66 MB) to"
say "https://huggingface.co/spaces/$HF_SPACE"
say "No API keys are uploaded: you add those in the next stage."
warn "The Space is created public, because the browser must reach it. Anyone can read its files."
if [[ ! -x "$PYTHON" ]]; then
  warn "No backend virtualenv at $PYTHON"
  note "Create it first (see the README, 'Backend setup'), then re-run this wizard."
  exit 1
fi
if confirm "Create the Space and upload now?"; then
  STAGE_DIR="$(mktemp -d)"
  HF_TOKEN="$HF_TOKEN" "$PYTHON" "$ROOT/backend/scripts/deploy_space.py" "$STAGE_DIR/space" --push "$HF_SPACE"
  rm -rf "$STAGE_DIR"
  note "Hugging Face now builds the image. The first build takes several minutes (torch and the"
  note "1.1 GB embedding model); you can keep going while it builds."
else
  say "Not uploaded. Re-run the wizard when you are ready."
  exit 0
fi
pause "Press Enter for the next stage."

stage "Space: API keys and address"
open_url "https://huggingface.co/spaces/$HF_SPACE/settings"
step "Scroll to 'Variables and secrets' and click 'New secret'."
step "Add GOOGLE_API_KEY, with the value from backend/.env."
step "Add WEB_SEARCH_API_KEY (the Tavily key), also from backend/.env."
note "This wizard deliberately does not ask for these two, so they never pass through it."
pause "Both secrets added?"
say ""
step "Open the Space page, click the ⋮ menu at the top right, choose 'Embed this Space', copy the Direct URL."
note "If you cannot find it: it is https://USER-SPACE.hf.space, lower case, with '-' for '_' and '.'."
open_url "https://huggingface.co/spaces/$HF_SPACE"
ask BACKEND_URL "Paste the Direct URL:"
BACKEND_URL="${BACKEND_URL%/}"
write_env BACKEND_URL "$BACKEND_URL"

stage "GitHub: push the code Vercel will build"
say "Vercel builds the frontend from GitHub, so the commits must be pushed."
git -C "$ROOT" fetch --quiet origin || warn "could not reach GitHub to compare"
BRANCH="$(git -C "$ROOT" rev-parse --abbrev-ref HEAD)"
AHEAD="$(git -C "$ROOT" rev-list --count '@{u}..HEAD' 2>/dev/null || echo '?')"
say "Branch: $BRANCH, commits not yet on GitHub: $AHEAD"
if [[ -n "$(git -C "$ROOT" status --porcelain --untracked-files=no)" ]]; then
  warn "You have uncommitted changes. They will not be deployed."
fi
if [[ "$BRANCH" != "main" ]]; then
  warn "You are not on main. Vercel's production branch is normally main."
fi
if [[ "$AHEAD" != "0" ]]; then
  if confirm "Run 'git push' now?"; then
    git -C "$ROOT" push
  else
    SKIPPED+=("git push (Vercel will build the old code until you do)")
    warn "Not pushed."
  fi
else
  say "Everything is already on GitHub."
fi
pause "Press Enter for the next stage."

stage "Vercel: deploy the frontend"
open_url "https://vercel.com/new"
step "Sign in with GitHub and import the LegalLens repository."
step "Under 'Root Directory' click Edit and choose: frontend"
step "Framework Preset should show Next.js."
step "Open 'Environment Variables' and add:"
say "      NEXT_PUBLIC_API_URL = $BACKEND_URL"
note "It is read when the site is built, so changing it later needs a redeploy."
step "Click Deploy and wait for it to finish."
step "Copy the production address of the site (e.g. https://legallens.vercel.app), with no path."
ask FRONTEND_URL "Paste the site address:"
FRONTEND_URL="${FRONTEND_URL%/}"
write_env FRONTEND_URL "$FRONTEND_URL"

stage "Space: allow the frontend's address"
say "The backend only accepts browser requests from addresses it is told about."
open_url "https://huggingface.co/spaces/$HF_SPACE/settings"
step "Under 'Variables and secrets', click 'New variable'."
step "Name: CORS_ORIGINS"
say "      Value: $FRONTEND_URL"
note "A variable is enough, it is not a secret. No trailing slash, no path."
step "Save. The Space restarts, which takes a minute or two."
pause "Variable saved?"

stage "Check the live deployment"
say "Waiting for the backend at $BACKEND_URL (a first build can take 10+ minutes)..."
READY=""
for _ in $(seq 1 60); do
  if READY="$(curl -fsS --max-time 10 "$BACKEND_URL/ready" 2>/dev/null)"; then break; fi
  READY=""
  printf '.'
  sleep 10
done
printf '\n'
if [[ -z "$READY" ]]; then
  warn "The backend did not report ready in 10 minutes."
  SKIPPED+=("Backend not ready: read the Space's Logs tab at https://huggingface.co/spaces/$HF_SPACE")
else
  say "/ready says: $READY"
  if [[ "$READY" == *'"fixture":false'* ]]; then
    say "✓ The full Corpus is loaded."
  else
    SKIPPED+=("The backend is serving only the sample Corpus: check the upload")
    warn "The backend is serving only the sample Corpus."
  fi
  ALLOW="$(curl -sS -i --max-time 15 -X OPTIONS "$BACKEND_URL/ask/stream" \
    -H "Origin: $FRONTEND_URL" -H 'Access-Control-Request-Method: POST' \
    -H 'Access-Control-Request-Headers: content-type' 2>/dev/null \
    | tr -d '\r' | grep -i '^access-control-allow-origin:' || true)"
  if [[ -n "$ALLOW" ]]; then
    say "✓ CORS allows the frontend ($ALLOW)"
  else
    SKIPPED+=("CORS_ORIGINS does not allow $FRONTEND_URL: check the variable and wait for the restart")
    warn "The backend does not allow $FRONTEND_URL yet."
  fi
fi
say ""
open_url "$FRONTEND_URL"
step "Ask: What is the punishment for murder?"
step "You should see the Stages, then the answer, the Trust label and Citations."
step "Check the disclaimer is visible and that 'Copy answer' works."
note "The free Space sleeps when idle, so the first question after a quiet spell is slow."
pause "Did it work?"

finish
}

run_wizard "$@"; exit
